```solidity: P256.sol
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {Math} from "../math/Math.sol";

library P256 {
    struct JPoint {
        uint256 x;
        uint256 y;
        uint256 z;
    }

    uint256 private constant P = 0xFFFFFFFF00000001000000000000000000000000FFFFFFFFFFFFFFFFFFFFFFFF;
    uint256 private constant A = 0xFFFFFFFF00000001000000000000000000000000FFFFFFFFFFFFFFFFFFFFFFFC;
    uint256 private constant B = 0x5AC635D8AA3A93E7B3EBBD55769886BC651D06B0CC53B0F63BCE3C3E27D2604B;
    uint256 private constant GX = 0x6B17D1F2E12C4247F8BCE6E563A440F277037D812DEB33A0F4A13945D898C296;
    uint256 private constant GY = 0x4FE342E2FE1A7F9B8EE7EB4A7C0F9E162BCE33576B315ECECBB6406837BF51F5;
    uint256 private constant N = 0xFFFFFFFF00000000FFFFFFFFFFFFFFFFBCE6FAADA7179E84F3B9CAC2FC632551;
    uint256 private constant HALF_N = N / 2;

    function verify(bytes32 h, bytes32 r, bytes32 s, bytes32 qx, bytes32 qy) internal view returns (bool) {
        (bool valid, bool supported) = _tryVerifyNative(h, r, s, qx, qy);
        if (supported) {
            return valid;
        }
        return verifySolidity(h, r, s, qx, qy);
    }

    function verifyNative(bytes32 h, bytes32 r, bytes32 s, bytes32 qx, bytes32 qy) internal view returns (bool) {
        (bool valid, bool supported) = _tryVerifyNative(h, r, s, qx, qy);
        if (!supported) {
            revert("P256: precompile not available");
        }
        return valid;
    }

    function _tryVerifyNative(bytes32 h, bytes32 r, bytes32 s, bytes32 qx, bytes32 qy) private view returns (bool valid, bool supported) {
        if (!_isProperSignature(r, s) || !isValidPublicKey(qx, qy)) {
            return (false, true);
        }

        (bool success, bytes memory data) = address(0x100).staticcall(
            abi.encode(h, r, s, qx, qy)
        );

        if (success && data.length == 0x20) {
            return (abi.decode(data, (bool)), true);
        }

        return (false, false);
    }

    function verifySolidity(bytes32 h, bytes32 r, bytes32 s, bytes32 qx, bytes32 qy) internal view returns (bool) {
        if (!_isProperSignature(r, s) || !isValidPublicKey(qx, qy)) {
            return false;
        }

        JPoint[16] memory points = _preComputeJacobianPoints(uint256(qx), uint256(qy));

        uint256 w = Math.invModPrime(uint256(s), N);
        uint256 u1 = mulmod(uint256(h), w, N);
        uint256 u2 = mulmod(uint256(r), w, N);

        (uint256 x, ) = _jMultShamir(points, u1, u2);

        return addmod(x % N, N - uint256(r), N) == 0;
    }

    function recovery(bytes32 h, uint8 v, bytes32 r, bytes32 s) internal view returns (bytes32 x, bytes32 y) {
        if (!_isProperSignature(r, s) || v > 1) {
            return (bytes32(0), bytes32(0));
        }

        uint256 rr = uint256(r);
        uint256 y2 = addmod(addmod(mulmod(mulmod(rr, rr, P), rr, P), mulmod(A, rr, P), P), B, P);
        uint256 yy = Math.modExp(y2, (P + 1) / 4, P);

        if (mulmod(yy, yy, P) != y2) {
            return (bytes32(0), bytes32(0));
        }

        if (uint8(yy & 1) != (1 - v)) {
            yy = P - yy;
        }

        JPoint[16] memory points = _preComputeJacobianPoints(rr, yy);

        uint256 w = Math.invModPrime(rr, N);
        uint256 u1 = mulmod(N - uint256(h), w, N);
        uint256 u2 = mulmod(uint256(s), w, N);

        (uint256 rx, uint256 ry) = _jMultShamir(points, u1, u2);

        return (bytes32(rx), bytes32(ry));
    }

    function isValidPublicKey(bytes32 x, bytes32 y) internal pure returns (bool result) {
        assembly ("memory-safe") {
            let p := 0xFFFFFFFF00000001000000000000000000000000FFFFFFFFFFFFFFFFFFFFFFFF
            let a := 0xFFFFFFFF00000001000000000000000000000000FFFFFFFFFFFFFFFFFFFFFFFC
            let b := 0x5AC635D8AA3A93E7B3EBBD55769886BC651D06B0CC53B0F63BCE3C3E27D2604B

            let xVal := mload(add(x, 0x20))
            let yVal := mload(add(y, 0x20))

            // x < p and y < p
            if or(iszero(lt(xVal, p)), iszero(lt(yVal, p))) {
                result := 0
                return(0x00, 0x00)
            }

            // y^2 mod p
            let y2 := mulmod(yVal, yVal, p)

            // x^3 + a*x + b mod p
            let x3 := mulmod(mulmod(xVal, xVal, p), xVal, p)
            let ax := mulmod(a, xVal, p)
            let rhs := addmod(addmod(x3, ax, p), b, p)

            result := eq(y2, rhs)
        }
    }

    function _isProperSignature(bytes32 r, bytes32 s) private pure returns (bool) {
        uint256 rInt = uint256(r);
        uint256 sInt = uint256(s);
        return rInt > 0 && rInt < N && sInt > 0 && sInt <= HALF_N;
    }

    function _affineFromJacobian(uint256 jx, uint256 jy, uint256 jz) private view returns (uint256 ax, uint256 ay) {
        if (jz == 0) {
            return (0, 0);
        }

        uint256 zinv = Math.invModPrime(jz, P);

        assembly ("memory-safe") {
            let p := 0xFFFFFFFF00000001000000000000000000000000FFFFFFFFFFFFFFFFFFFFFFFF
            let zzinv := mulmod(zinv, zinv, p)
            ax := mulmod(jx, zzinv, p)
            ay := mulmod(mulmod(jy, zzinv, p), zinv, p)
        }
    }

    function _jAdd(JPoint memory p1, uint256 x2, uint256 y2, uint256 z2) private pure returns (uint256 rx, uint256 ry, uint256 rz) {
        assembly ("memory-safe") {
            let p := 0xFFFFFFFF00000001000000000000000000000000FFFFFFFFFFFFFFFFFFFFFFFF
            let a := 0xFFFFFFFF00000001000000000000000000000000FFFFFFFFFFFFFFFFFFFFFFFC
            let x1 := mload(p1)
            let y1 := mload(add(p1, 0x20))
            let z1 := mload(add(p1, 0x40))

            let zz1 := mulmod(z1, z1, p)
            let zz2 := mulmod(z2, z2, p)
            let u1 := mulmod(x1, zz2, p)
            let u2 := mulmod(x2, zz1, p)
            let z2z2z2 := mulmod(z2, zz2, p)
            let z1z1z1 := mulmod(z1, zz1, p)
            let s1 := mulmod(y1, z2z2z2, p)
            let s2 := mulmod(y2, z1z1z1, p)

            let h_ := addmod(u2, sub(p, u1), p)
            let r_ := addmod(s2, sub(p, s1), p)

            // if h == 0 and r == 0, points are identical
            let hIsZero := iszero(h_)
            let rIsZero := iszero(r_)

            switch and(hIsZero, rIsZero)
            case 1 {
                // Points are identical, perform doubling
                let yy := mulmod(y1, y1, p)
                let m := addmod(mulmod(3, mulmod(x1, x1, p), p), mulmod(a, mulmod(zz1, zz1, p), p), p)
                let s := mulmod(4, mulmod(x1, yy, p), p)
                rx := addmod(mulmod(m, m, p), sub(p, mulmod(2, s, p)), p)
                ry := addmod(mulmod(m, addmod(s, sub(p, rx), p), p), sub(p, mulmod(8, mulmod(yy, yy, p), p)), p)
                rz := mulmod(2, mulmod(y1, z1, p), p)
            }
            default {
                // Points are different or h == 0 (inverse)
                let hh := mulmod(h_, h_, p)
                let hhh := mulmod(hh, h_, p)
                let u1hh := mulmod(u1, hh, p)
                rx := addmod(addmod(mulmod(r_, r_, p), sub(p, hhh), p), sub(p, mulmod(2, u1hh, p)), p)
                ry := addmod(mulmod(r_, addmod(u1hh, sub(p, rx), p), p), sub(p, mulmod(s1, hhh, p)), p)
                rz := mulmod(mulmod(z1, z2, p), h_, p)
            }
        }
    }

    function _jDouble(uint256 x, uint256 y, uint256 z) private pure returns (uint256 rx, uint256 ry, uint256 rz) {
        assembly ("memory-safe") {
            let p := 0xFFFFFFFF00000001000000000000000000000000FFFFFFFFFFFFFFFFFFFFFFFF
            let a := 0xFFFFFFFF00000001000000000000000000000000FFFFFFFFFFFFFFFFFFFFFFFC
            let yy := mulmod(y, y, p)
            let zz := mulmod(z, z, p)
            let m := addmod(mulmod(3, mulmod(x, x, p), p), mulmod(a, mulmod(zz, zz, p), p), p)
            let s := mulmod(4, mulmod(x, yy, p), p)
            rx := addmod(mulmod(m, m, p), sub(p, mulmod(2, s, p)), p)
            ry := addmod(mulmod(m, addmod(s, sub(p, rx), p), p), sub(p, mulmod(8, mulmod(yy, yy, p), p)), p)
            rz := mulmod(2, mulmod(y, z, p), p)
        }
    }

    function _jMultShamir(JPoint[16] memory points, uint256 u1, uint256 u2) private view returns (uint256 rx, uint256 ry) {
        uint256 x = 0;
        uint256 y = 0;
        uint256 z = 0;

        for (uint256 i = 0; i < 128; i++) {
            if (z > 0) {
                (x, y, z) = _jDouble(x, y, z);
                (x, y, z) = _jDouble(x, y, z);
            }

            uint256 bits1 = (u1 >> 504) & 3;
            uint256 bits2 = (u2 >> 504) & 3;
            uint256 idx = bits1 * 4 + bits2;

            JPoint memory lookup = points[idx];

            if (lookup.z != 0) {
                if (z == 0) {
                    x = lookup.x;
                    y = lookup.y;
                    z = lookup.z;
                } else {
                    (x, y, z) = _jAdd(lookup, x, y, z);
                }
            }

            u1 <<= 2;
            u2 <<= 2;
        }

        return _affineFromJacobian(x, y, z);
    }

    function _preComputeJacobianPoints(uint256 px, uint256 py) private pure returns (JPoint[16] memory points) {
        points[0] = JPoint(0, 0, 0);
        points[1] = JPoint(px, py, 1);
        points[4] = JPoint(GX, GY, 1);

        (uint256 x2, uint256 y2, uint256 z2) = _jDouble(px, py, 1);
        points[2] = JPoint(x2, y2, z2);

        (uint256 xg2, uint256 yg2, uint256 zg2) = _jDouble(GX, GY, 1);
        points[8] = JPoint(xg2, yg2, zg2);

        {
            (uint256 x3, uint256 y3, uint256 z3) = _jAdd(points[2], px, py, 1);
            points[3] = JPoint(x3, y3, z3);
        }

        {
            (uint256 x5, uint256 y5, uint256 z5) = _jAdd(points[4], px, py, 1);
            points[5] = JPoint(x5, y5, z5);
        }

        {
            (uint256 x6, uint256 y6, uint256 z6) = _jAdd(points[4], x2, y2, z2);
            points[6] = JPoint(x6, y6, z6);
        }

        {
            (uint256 x7, uint256 y7, uint256 z7) = _jAdd(points[4], points[3].x, points[3].y, points[3].z);
            points[7] = JPoint(x7, y7, z7);
        }

        {
            (uint256 x9, uint256 y9, uint256 z9) = _jAdd(points[8], px, py, 1);
            points[9] = JPoint(x9, y9, z9);
        }

        {
            (uint256 xa, uint256 ya, uint256 za) = _jAdd(points[8], x2, y2, z2);
            points[0x0a] = JPoint(xa, ya, za);
        }

        {
            (uint256 xb, uint256 yb, uint256 zb) = _jAdd(points[8], points[3].x, points[3].y, points[3].z);
            points[0x0b] = JPoint(xb, yb, zb);
        }

        {
            (uint256 xg3, uint256 yg3, uint256 zg3) = _jAdd(points[8], GX, GY, 1);
            points[0x0c] = JPoint(xg3, yg3, zg3);
        }

        {
            (uint256 xd, uint256 yd, uint256 zd) = _jAdd(points[0x0c], px, py, 1);
            points[0x0d] = JPoint(xd, yd, zd);
        }

        {
            (uint256 xe, uint256 ye, uint256 ze) = _jAdd(points[0x0c], x2, y2, z2);
            points[0x0e] = JPoint(xe, ye, ze);
        }

        {
            (uint256 xf, uint256 yf, uint256 zf) = _jAdd(points[0x0c], points[3].x, points[3].y, points[3].z);
            points[0x0f] = JPoint(xf, yf, zf);
        }
    }

    function _jAddPoint(JPoint memory p1, JPoint memory p2) private pure returns (JPoint memory) {
        (uint256 rx, uint256 ry, uint256 rz) = _jAdd(p1, p2.x, p2.y, p2.z);
        return JPoint(rx, ry, rz);
    }

    function _jDoublePoint(JPoint memory p) private pure returns (JPoint memory) {
        (uint256 rx, uint256 ry, uint256 rz) = _jDouble(p.x, p.y, p.z);
        return JPoint(rx, ry, rz);
    }
}
```

