            rx := addmod(sub(p, mulmod(2, s, p)), mulmod(m, m, p), p)
            ry := mulmod(sub(p, rx), m, p)
            ry := addmod(sub(p, mulmod(s, ry, p)), mulmod(8, mulmod(mulmod(yy, yy, p), 1, p), p), p)
            rz := mulmod(2, mulmod(y1, z1, p), p)
        }
        default {
            // Points are different
            let hhh := mulmod(hh, h_, p)
            rx := addmod(sub(p, mulmod(mulmod(r_, r_, p), 1, p)), mulmod(2, mulmod(u1, hh, p), p), p)
            rx := addmod(rx, sub(p, hhh), p)
            ry := mulmod(sub(p, rx), r_, p)
            ry := addmod(sub(p, mulmod(u1, hh, p)), ry, p)
            ry := mulmod(sub(p, ry), r_, p)
            ry := addmod(ry, sub(p, mulmod(s1, hhh, p)), p)
            rz := mulmod(z1, mulmod(z2, mulmod(z2, z2, p), p), p)
            rz := mulmod(rz, h_, p)
        }
    }
}

